@@ -0,0 +1,38 @@
+export interface BucketOptions {
+  capacity: number;
+  refillPerSecond: number;
+  now?: () => number;
+}
+
+/** Token bucket with lazy refill. One bucket per tenant. */
+export class TokenBucket {
+  #tokens: number;
+  #updatedAt: number;
+  readonly #capacity: number;
+  readonly #refillPerMs: number;
+  readonly #now: () => number;
+
+  constructor({ capacity, refillPerSecond, now = Date.now }: BucketOptions) {
+    this.#capacity = capacity;
+    this.#refillPerMs = refillPerSecond / 1000;
+    this.#now = now;
+    this.#tokens = capacity;
+    this.#updatedAt = now();
+  }
+
+  take(cost = 1): boolean {
+    this.#refill();
+    if (this.#tokens < cost) return false;
+    this.#tokens -= cost;
+    return true;
+  }
+
+  #refill(): void {
+    const now = this.#now();
+    const elapsed = now - this.#updatedAt;
+    this.#tokens = Math.min(this.#capacity, this.#tokens + elapsed * this.#refillPerMs);
+    this.#updatedAt = now;
+  }
+}
+
+export const retryAfterSeconds = (bucket: TokenBucket) => 1;

